use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(),
    ensures
        new_list.len() == list.len() - 1,
        // Elements before the removed one stay the same
        forall|i: int|
            0 <= i && i < (k - 1) as int
            ==> new_list[i] == list[i],
        // Elements after the removed one shift left by 1
        forall|i: int|
            (k - 1) as int <= i && i < new_list.len() as int
            ==> new_list[i] == list[i + 1],
{
    // Assumptions: list is non-empty and 1 <= k < list.len()
    let idx = k - 1; // convert 1-based k to 0-based index

    let mut new_list = Vec::with_capacity(list.len() - 1);
    new_list.extend_from_slice(&list[..idx]);        // elements before k
    new_list.extend_from_slice(&list[idx + 1..]);    // elements after k

    new_list
}

} // verus!

